"""Proposed W2.3 contracts on owned TEST_ONLY generated bytes only.

No future API is imported at collection. The first case uses the existing
ReportBuilder interface and must fail on v1 versus v2 after real registration.
This preparation has not been imported, discovered or executed.
"""
import copy
import hashlib
import json
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

import report_generation
from gait_events import orient_event_candidates, propose_extrema
from manual_assessment_entry import manual_assessment_context, publish_manual_assessment_entry
from native_evidence_fixture import complete_native_fixture
from report_builder import ReportBuilder
from run_pipeline import validate_run_evidence
from session_contract import ROLES, load_session, sha256_file
from session_index import SessionIndex
from session_library import SessionLibrary
from session_metadata_revision import publish_metadata_revision, read_metadata_state
from setup_project import register_captures
from test_manual_assessment_provenance import generated_trajectory

SID = "TEST_ONLY-report-current-context"
MANIFEST_V2 = "kinelab.report-generation.v2"
MANUAL_CONTEXT = "kinelab.report-manual-context.v1"


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


def initial_metadata():
    return {"schema": "kinelab.session-metadata.v1", "subject_id": "sub-" + "1" * 32,
            "operator_id": "op-" + "2" * 32, "task_id": "TEST_ONLY-report-task",
            "protocol_id": "TEST_ONLY-report-protocol", "protocol_version": "1",
            "laterality": "bilateral", "confirmed": True,
            "confirmed_at": "2026-10-29T16:00:00+00:00"}


class ReportCurrentContextTests(unittest.TestCase):
    def setUp(self):
        owned = tempfile.TemporaryDirectory(prefix="TEST_ONLY-report-context-")
        self.addCleanup(owned.cleanup)
        self.base = Path(owned.name)
        self.projects = self.base / "TEST_ONLY-projects"
        self.folder = self.projects / SID
        (self.folder / "raw").mkdir(parents=True)
        (self.folder / "Config.toml").write_text("# TEST_ONLY generated\n[project]\n", encoding="utf-8")
        for role in ROLES:
            (self.folder / "raw" / f"{role}.mp4").write_bytes(("TEST_ONLY non-codec " + role).encode())
        self.initial = initial_metadata()
        self.write(self.folder / "session-template.json", {
            "schema": "kinelab.session-template.v1", "session_id": SID,
            "kind": "real", "metadata": self.initial})
        self.session = register_captures(self.folder, SID, metadata=self.initial)
        self.assertEqual(load_session(self.folder)["session_id"], SID)
        complete_native_fixture(self.folder, "", through="poseEstimation")
        validate_run_evidence(self.folder, through="poseEstimation")
        self.index = SessionIndex(self.base / "TEST_ONLY-index.db", self.projects)
        self.addCleanup(self.index.close)
        # Only codec observation is doubled; all provenance, audit and reports are real.
        probe = patch("session_index.probe_clip", return_value={
            "width": 1024, "height": 576, "fps": 30, "duration": 8})
        probe.start()
        self.addCleanup(probe.stop)
        self.index.reindex()
        state = read_metadata_state(self.index, SID)
        self.assertEqual(state["status"], "AVAILABLE", state)
        self.assertEqual(state["origin"]["sha256"], sha256_file(self.folder / "session.json"))
        self.assertEqual(state["metadata"], self.initial)
        self.assertNotIn(self.index.get_passport(SID)["state"], ("EVIDENCE_INVALID", "EVIDENCE_UNVERIFIED"))
        self.builder = ReportBuilder(self.projects, self.index)
        self.originals = {relative: (self.folder / relative).read_bytes() for relative in (
            "session.json", "session-template.json", "Config.toml", "run.json",
            *(f"raw/{role}.mp4" for role in ROLES))}

    @staticmethod
    def write(path, value):
        path.write_bytes(canonical(value))

    @staticmethod
    def tree(folder):
        result = {}
        for path in sorted(folder.rglob("*")):
            relative = path.relative_to(folder).as_posix()
            observed = path.stat()
            result[relative + ("/" if path.is_dir() else "")] = (
                observed.st_dev, observed.st_ino,
                None if path.is_dir() else hashlib.sha256(path.read_bytes()).hexdigest())
        return result

    def context(self):
        reader = getattr(report_generation, "current_report_context", None)
        self.assertTrue(callable(reader), "W2.3 content-only context reader is required")
        before, audit = self.tree(self.folder), self.index.verify_audit()
        value = reader(self.index, SID)
        self.assertEqual(self.tree(self.folder), before, "context read must create no anchor or evidence")
        self.assertEqual(self.index.verify_audit(), audit)
        self.assertEqual(value["schema"], "kinelab.report-context.v1")
        self.assertEqual(value["session_id"], SID)
        bound = {key: value[key] for key in (
            "schema", "session_id", "input_policy", "inputs", "origin_sha256", "run_sha256",
            "metadata_context_sha256", "manual_assessment_context")}
        self.assertEqual(value["report_context_sha256"], digest(bound))
        manual = value["manual_assessment_context"]
        self.assertEqual(set(manual), {"schema", "assessments", "unavailable_assessments", "sha256"})
        self.assertEqual(manual["schema"], MANUAL_CONTEXT)
        self.assertEqual(manual["sha256"], digest({key: val for key, val in manual.items() if key != "sha256"}))
        return value

    def generate_v2(self, **kwargs):
        files = self.builder.generate_reports(SID, **kwargs)
        directory = files["json"].parent
        document = json.loads((directory / "manifest.json").read_bytes())
        # Deliberately first business assertion: existing registered producer emits v1.
        self.assertEqual(document["schema"], MANIFEST_V2, "registered current-context publication requires v2")
        return files, document

    def head(self, files):
        directory = files["json"].parent
        return {"generation": directory.name, "manifest_sha256": sha256_file(directory / "manifest.json")}

    def correct_metadata(self):
        state = read_metadata_state(self.index, SID)
        changed = copy.deepcopy(state["metadata"])
        changed.update(subject_id="sub-" + "3" * 32, confirmed_at="2026-10-29T16:01:00+00:00")
        return publish_metadata_revision(self.index, SID, metadata=changed,
            expected_origin_sha256=state["origin"]["sha256"],
            expected_head_sha256=None if state["head"] is None else state["head"]["sha256"],
            operation_id="4" * 32, reason_code="operator_correction", confirm=True)

    def assert_originals(self):
        for relative, raw in self.originals.items():
            self.assertEqual((self.folder / relative).read_bytes(), raw, relative)

    def test_00_R1_registered_initial_publication_is_v2_with_exact_receipt_and_three_files(self):
        files, manifest = self.generate_v2()
        context = self.context()
        self.assertEqual(set(manifest), {"schema", "session_id", "generation", "input_policy", "inputs", "files",
            "supersedes", "origin_sha256", "run_sha256", "metadata_context_sha256",
            "manual_assessment_context", "report_context_sha256"})
        self.assertIsNone(manifest["supersedes"])
        for key in ("input_policy", "inputs", "origin_sha256", "run_sha256", "metadata_context_sha256",
                    "manual_assessment_context", "report_context_sha256"):
            self.assertEqual(manifest[key], context[key], key)
        self.assertEqual({path.name for path in files["json"].parent.iterdir()}, {
            "manifest.json", f"{SID}-research-report.pdf", f"{SID}-research-summary.json", f"{SID}-metrics.csv"})
        row = self.index.conn.execute("SELECT details_json FROM audit_events WHERE session_id=? AND event_type='REPORT_PUBLISHED'", (SID,)).fetchone()
        self.assertEqual(json.loads(row[0]), {"schema": "kinelab.report-publication.v2", **self.head(files),
            "supersedes": None, "report_context_sha256": context["report_context_sha256"]})
        summary = json.loads(files["json"].read_bytes())
        self.assertIs(summary["clinical_accuracy_verified"], False)
        self.assertIs(summary["physical_accuracy_verified"], False)
        self.assertEqual(summary["measurement_count"], 0)
        self.assert_originals()

    def test_R2_audited_metadata_supersedes_without_rewriting_old_generation(self):
        first, old = self.generate_v2()
        frozen = self.tree(first["json"].parent)
        old_events = [tuple(row) for row in self.index.conn.execute("SELECT * FROM audit_events ORDER BY id")]
        self.correct_metadata()
        current = self.context()
        self.assertNotEqual(current["metadata_context_sha256"], old["metadata_context_sha256"])
        second, new = self.generate_v2(expected_report_head=self.head(first),
            expected_report_context_sha256=current["report_context_sha256"])
        self.assertEqual(new["supersedes"], self.head(first))
        self.assertNotEqual(second["json"].parent, first["json"].parent)
        self.assertEqual(self.tree(first["json"].parent), frozen)
        rows = [tuple(row) for row in self.index.conn.execute("SELECT * FROM audit_events ORDER BY id")]
        self.assertEqual(rows[:len(old_events)], old_events)
        self.assertEqual(len(report_generation.committed_reports(self.index, SID, check_inputs=False)), 6)
        self.assert_originals()

    def test_R4_unchanged_context_and_incorrect_or_omitted_cas_refuse_without_writes(self):
        first, _ = self.generate_v2()
        same = self.context()
        before, audit = self.tree(self.folder), self.index.verify_audit()
        with self.assertRaises(ValueError):
            self.builder.generate_reports(SID, expected_report_head=self.head(first),
                expected_report_context_sha256=same["report_context_sha256"])
        self.assertEqual(self.tree(self.folder), before)
        self.assertEqual(self.index.verify_audit(), audit)
        self.correct_metadata()
        current = self.context()
        for kwargs in ({}, {"expected_report_head": None, "expected_report_context_sha256": current["report_context_sha256"]},
                       {"expected_report_head": self.head(first), "expected_report_context_sha256": same["report_context_sha256"]}):
            with self.subTest(kwargs=kwargs):
                before, audit = self.tree(self.folder), self.index.verify_audit()
                with self.assertRaises(ValueError):
                    self.builder.generate_reports(SID, **kwargs)
                self.assertEqual(self.tree(self.folder), before)
                self.assertEqual(self.index.verify_audit(), audit)

    def test_R5_older_artifact_tamper_blocks_history_current_context_and_publication(self):
        first, _ = self.generate_v2()
        self.correct_metadata()
        current = self.context()
        second, _ = self.generate_v2(expected_report_head=self.head(first),
            expected_report_context_sha256=current["report_context_sha256"])
        old_pdf = first["pdf"]
        old_pdf.write_bytes(old_pdf.read_bytes() + b"TEST_ONLY deliberate tamper")
        before, audit = self.tree(self.folder), self.index.verify_audit()
        reader = getattr(report_generation, "current_report_context", None)
        self.assertTrue(callable(reader))
        with self.assertRaises(ValueError):
            report_generation.committed_reports(self.index, SID, check_inputs=False)
        with self.assertRaises(ValueError):
            reader(self.index, SID)
        with self.assertRaises(ValueError):
            self.builder.generate_reports(SID, expected_report_head=self.head(second),
                expected_report_context_sha256=current["report_context_sha256"])
        self.assertEqual(self.tree(self.folder), before, "never heal changed historical evidence")
        self.assertEqual(self.index.verify_audit(), audit)

    def test_R8_portable_manual_receipt_set_changes_digest_and_marks_stale_metadata_unavailable(self):
        directory = self.folder / "assessment-inputs" / "TEST_ONLY-gait"
        directory.mkdir(parents=True)
        trajectory = generated_trajectory(self.session["captures"]["cam01_trial"]["sha256"])
        candidates = orient_event_candidates(propose_extrema(
            trajectory, "cam01_trial", self.session["captures"]["cam01_trial"]["sha256"],
            image_width=1024, image_height=576), screen_forward="right")
        self.write(directory / "trajectory.json", trajectory)
        self.write(directory / "candidates.json", candidates)
        before = self.context()
        ui = manual_assessment_context(self.index, SID)
        item = ui["input_sets"][0]
        receipt = publish_manual_assessment_entry(self.index, SID, {
            "operation_id": "5" * 32, "context_sha256": ui["context_sha256"],
            "metadata_context_sha256": ui["metadata_context_sha256"], "input_id": item["input_id"],
            "source_sha256": item["source_sha256"], "reviewer": "TEST_ONLY generated reviewer",
            "annotation_origin": "human_observed_video_frames", "labels": [
                {"frame_index": 50, "side": "left", "event_type": "initial_contact"}],
            "tolerance_frames": 3, "confirm": True})
        after = self.context()
        self.assertEqual(manual_assessment_context(self.index, SID)["context_sha256"], ui["context_sha256"])
        self.assertNotEqual(after["manual_assessment_context"]["sha256"], before["manual_assessment_context"]["sha256"])
        self.assertEqual(after["manual_assessment_context"]["assessments"], [receipt])
        self.assertEqual(after["manual_assessment_context"]["unavailable_assessments"], [])
        self.correct_metadata()
        stale = self.context()["manual_assessment_context"]
        self.assertEqual(stale["assessments"], [])
        self.assertEqual(stale["unavailable_assessments"], [{"operation_id": "5" * 32, "reason": "METADATA_CONTEXT_CHANGED"}])
        self.assert_originals()

    def test_R10_initial_unregistered_legacy_interface_remains_v1(self):
        folder = SessionLibrary(self.projects).create_session("TEST_ONLY-legacy-report", kind="demo")
        self.index.reindex()
        self.assertEqual(read_metadata_state(self.index, folder.name)["status"], "UNAVAILABLE")
        files = self.builder.generate_reports(folder.name)
        manifest = json.loads((files["json"].parent / "manifest.json").read_bytes())
        self.assertEqual(manifest["schema"], "kinelab.report-generation.v1")
        self.assertEqual(len(report_generation.committed_reports(self.index, folder.name)), 3)
